), expected_functions AS (
 SELECT e.key,e.value FROM refs r CROSS JOIN LATERAL jsonb_each(r.fixture_functions) e
), function_comparison AS (
 SELECT coalesce(e.key,a.name) object,e.value #>> '{}' expected_088_sha256,
 a.actual_sha256,r.accepted_functions->coalesce(e.key,a.name)->>'hash' accepted_sha256,
 r.accepted_functions->coalesce(e.key,a.name)->>'source' accepted_source,
 r.function_body_origin->split_part(coalesce(e.key,a.name),'(',1) last_literal_body_migration,
 a.v actual_definition,
 CASE WHEN a.name IS NULL THEN 'OBJECT_MISSING'
 WHEN e.key IS NULL THEN 'EXTRA_OVERLOAD_OR_BATCH_ALREADY_PRESENT'
 WHEN a.actual_sha256=r.accepted_functions->coalesce(e.key,a.name)->>'hash'
   AND a.actual_sha256<>e.value #>> '{}' THEN 'MATCHES_ACCEPTED_CONTRACT_BUT_088_BASELINE_DIFFERS'
 WHEN a.actual_sha256=e.value #>> '{}' AND
   (r.accepted_functions->coalesce(e.key,a.name)->>'hash') IS NOT NULL AND
   a.actual_sha256<>r.accepted_functions->coalesce(e.key,a.name)->>'hash'
   THEN 'MATCHES_FIXTURE_BUT_CONFLICTS_WITH_ACCEPTED_CONTRACT_REVIEW_REQUIRED'
 WHEN a.actual_sha256=e.value #>> '{}' THEN 'MATCHES_088_EXPECTATION'
 WHEN r.accepted_functions->coalesce(e.key,a.name)->>'hash' IS NULL
   THEN 'NO_INDEPENDENT_PIN_REVIEW_DEFINITION_AND_GRANTS'
 ELSE 'DIFFERS_FROM_BOTH_REFERENCES_REVIEW_REQUIRED' END finding
 FROM expected_functions e FULL JOIN functions a ON a.name=e.key CROSS JOIN refs r
