 jsonb_build_object(
 'policies',(SELECT coalesce(jsonb_agg(p ORDER BY p->>'policyname' COLLATE "C"),'[]')
   FROM jsonb_array_elements(r.accepted_078_additions->'policies') x(p) WHERE p->>'tablename'=t.name),
 'triggers',(SELECT coalesce(jsonb_agg(g ORDER BY g->>'name' COLLATE "C"),'[]')
   FROM jsonb_array_elements(r.accepted_078_additions->'triggers') x(g) WHERE g->>'table'=t.name)) expected_078_additions
 FROM tables t CROSS JOIN refs r
), table_comparison AS (
 SELECT e.key object,e.value #>> '{}' expected_088_sha256,t.actual_088_sha256,
 r.accepted_071_tables->>e.key accepted_071_sha256,encode(sha256(convert_to((t.projection_071)::text,'UTF8')),'hex') actual_071_projection_sha256,
 r.accepted_078_security->>e.key accepted_078_security_sha256,encode(sha256(convert_to((t.security_078)::text,'UTF8')),'hex') actual_078_security_sha256,
 t.expected_078_additions,t.actual_078_additions,
 t.actual_078_additions IS NOT DISTINCT FROM t.expected_078_additions additions_078_exact,
 r.table_ddl_origin->e.key table_ddl_migrations,
 t.v actual_definition,
 CASE WHEN t.name IS NULL THEN 'OBJECT_MISSING'
 WHEN t.actual_088_sha256=e.value #>> '{}' THEN 'MATCHES_088_EXPECTATION'
 WHEN encode(sha256(convert_to((t.projection_071)::text,'UTF8')),'hex')=r.accepted_071_tables->>e.key
   AND t.actual_078_additions=t.expected_078_additions
   AND (r.accepted_078_security->>e.key IS NULL OR encode(sha256(convert_to((t.security_078)::text,'UTF8')),'hex')=r.accepted_078_security->>e.key)
   THEN '071_TABLE_AND_EXACT_078_DELTAS_MATCH_REVIEW_COLUMN_ACLS_SEPARATELY'
 ELSE 'REVIEW_COMPONENTS_AGAINST_ACCEPTED_MIGRATIONS' END finding,
 (SELECT coalesce(jsonb_agg(jsonb_build_object('column',coalesce(bc->>'name',ac->>'name'),
   'expected_pre078_preserved_column',bc,'actual',ac) ORDER BY coalesce(bc->>'name',ac->>'name') COLLATE "C"),'[]')
  FROM jsonb_array_elements(coalesce(r.accepted_column_evidence->e.key,'[]')) b(bc)
  FULL JOIN jsonb_array_elements(coalesce(t.v->'columns','[]')) a(ac) ON bc->>'name'=ac->>'name'
  WHERE r.accepted_column_evidence ? e.key AND bc IS DISTINCT FROM ac-'acl') column_evidence_differences
 FROM refs r CROSS JOIN LATERAL jsonb_each(r.fixture_tables) e LEFT JOIN table_parts t ON t.name=e.key
)
SELECT jsonb_build_object(
 'diagnostic_only',true,'business_rows_read',false,'business_rpc_executed',false,'production_mutation',false,
 'candidate_sha256','02010ab7b56100146c455d582e40e43e28ebf761beb7068e220dd95a1184487c',
 'server_version',current_setting('server_version'),'server_version_num',current_setting('server_version_num'),
 'search_path',current_setting('search_path'),'database_collation',(SELECT datcollate FROM pg_database WHERE datname=current_database()),
 'interpretation','This is evidence, not a PASS gate. Unmatched objects remain unresolved. Full function hashes include ACL and execute rights. Table projection checks exact 078 additions separately; column ACLs remain in actual_definition and must not be discarded. PostgreSQL NOT NULL constraints are inspected through attnotnull, not contype n.',
 'functions',(SELECT coalesce(jsonb_agg(to_jsonb(f) ORDER BY object COLLATE "C"),'[]') FROM function_comparison f),
 'tables',(SELECT coalesce(jsonb_agg(to_jsonb(t) ORDER BY object COLLATE "C"),'[]') FROM table_comparison t),
 'not_null_constraint_representation',(SELECT coalesce(jsonb_agg(jsonb_build_object('table',c.relname,'constraint',n.conname,'definition',pg_get_constraintdef(n.oid)) ORDER BY c.relname COLLATE "C",n.conname COLLATE "C"),'[]') FROM pg_constraint n JOIN pg_class c ON c.oid=n.conrelid WHERE c.relnamespace='public'::regnamespace AND c.relname IN ('finance_expenses','finance_expense_settlements','finance_expense_obligations','finance_expense_tax_reviews','finance_expense_audit','finance_expense_obligation_waivers','finance_payouts','finance_payout_allocations','finance_payout_audit','finance_cash_transactions','finance_cash_transaction_audit_events','finance_outgoing_wht_obligations','finance_payees','finance_payee_destinations','finance_account_opening_balances','finance_treasury_account_authorities') AND n.contype='n')
) diagnostic;
